}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args    _args)
{
    SalesQuotationTable             locSalesQuotationTable;

    while select locSalesQuotationTable
        where locSalesQuotationTable.QuotationStatus == SalesQuotationStatus::Sent
    {
        AVASpecialDiscQuotation     specialDiscQuotation = AVASpecialDiscQuotation::find(locSalesQuotationTable.QuotationId);

        locSalesQuotationTable.AVASpecialDiscFactor  = specialDiscQuotation.AllDiscountFactor;
        ttsbegin;
        locSalesQuotationTable.selectForUpdate(true);
        locSalesQuotationTable.doUpdate();
        ttscommit;
    }
}
